package app

import (
	"strings"

	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"

	"github.com/anthnel/devdesk/internal/ui/overlay"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// View is the program's frame. The router is the only place that sets the
// terminal state (alternate screen now), the views only provide content.
func (a *App) View() tea.View {
	v := tea.NewView(a.Render())
	v.AltScreen = true
	v.ReportFocus = true // mode 1004: BlurMsg/FocusMsg (DEVDESK-210)
	v.BackgroundColor = terminalBackground(a.colorProfile, theme.ColorBackground)
	v.ProgressBar = terminalProgress(a.progress) // DEVDESK-211
	return v
}

// Render renders the interface: header, title line, viewport, footer (Rule 124).
// An open overlay replaces the whole thing.
func (a *App) Render() string {
	if overlay := a.activeOverlay(); overlay != "" {
		return lipgloss.Place(a.width, a.height, lipgloss.Center, lipgloss.Center, overlay,
			lipgloss.WithWhitespaceStyle(lipgloss.NewStyle().Background(theme.ColorBackground)))
	}

	header := a.renderHeader() + "\n" + a.renderTitleLine()
	body := a.renderBody()
	footer := a.renderViewFooter()
	inner := fitHeight(header, body, footer, a.height)

	placed := lipgloss.Place(a.width, a.height, lipgloss.Left, lipgloss.Top, inner,
		lipgloss.WithWhitespaceStyle(lipgloss.NewStyle().Background(theme.ColorBackground)))
	return a.withPalette(placed)
}

// withPalette draws the open command palette over the final screen. The
// composition happens after fitHeight and Place, on exactly height lines of
// width cells, so the geometry is in screen rows whatever the view is.
func (a *App) withPalette(screen string) string {
	lines := a.paletteLines()
	if len(lines) == 0 {
		return screen
	}
	r := a.paletteRect()
	composed := overlay.Compose(strings.Split(screen, "\n"), lines, r.X, r.Y, a.width)
	return strings.Join(composed, "\n")
}

// fitHeight stacks header, body and footer in at most height lines.
// lipgloss.Place pads a short block but never crops a tall one, so on a very
// small terminal (header 8 + title 1 + the viewport's minimum + footer) the
// frame would be taller than the screen. The surplus is taken from the body
// first, bottom lines first: the footer carries the messages, so it outranks
// viewport rows. If header and footer alone are taller than the terminal, the
// stack is cut to its first height lines, the simplest floor. At normal
// heights nothing is cut.
func fitHeight(header, body, footer string, height int) string {
	parts := []string{header}
	if body != "" {
		parts = append(parts, body)
	}
	if footer != "" {
		parts = append(parts, footer)
	}
	lines := strings.Split(strings.Join(parts, "\n"), "\n")
	excess := len(lines) - height
	if height <= 0 || excess <= 0 {
		return strings.Join(lines, "\n")
	}

	headerLen := strings.Count(header, "\n") + 1
	bodyLen := 0
	if body != "" {
		bodyLen = strings.Count(body, "\n") + 1
	}
	cut := min(excess, bodyLen)
	if cut > 0 {
		end := headerLen + bodyLen
		lines = append(lines[:end-cut], lines[end:]...)
	}
	if len(lines) > height {
		lines = lines[:height]
	}
	return strings.Join(lines, "\n")
}

// activeOverlay returns the overlay to draw instead of the view, or "" when
// there is none. The order matches the one handleKeyMsg dispatches in, so the
// overlay holding the keyboard is the one on screen.
func (a *App) activeOverlay() string {
	switch {
	case a.switchingTo != "":
		return a.renderContextSwitchingOverlay()
	case a.showHelp:
		return a.renderHelpOverlay()
	case a.showContextList:
		return a.renderContextListOverlay()
	}
	return ""
}

// renderBody fills the viewport with the active view's content, padded to the
// full inner width so no line shows the terminal's own background (Rule 115).
func (a *App) renderBody() string {
	content := "View not found: " + string(a.currentView)
	if view, ok := a.views[a.currentView]; ok {
		content = view.Render()
	}

	innerWidth := a.viewport.Width() - 2 // -2 for the borders
	if a.frameless() {
		innerWidth = a.viewport.Width()
	}
	a.viewport.SetContent(lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorText).
		Width(innerWidth).
		Render(content))

	body := a.viewport.View()

	// Rule 136: with a filter bar below it, the viewport's bottom corners become
	// T-junctions so the two form one closed rectangle.
	if view, ok := a.views[a.currentView]; ok {
		if fbv, ok := view.(FilterBarView); ok && fbv.FilterBarVisible() {
			body = replaceViewportBottomCorners(body)
		}
	}
	return body
}

// renderTitleLine draws the viewport's top border carrying the view's title —
// or, for a frameless view, a titled rule with no corners: GetTitle() keeps a
// reader oriented where a top border would draw the top of a nonexistent box.
func (a *App) renderTitleLine() string {
	title := ""
	if view, ok := a.views[a.currentView]; ok {
		if hv, implements := view.(HeaderView); implements {
			title = hv.GetTitle()
		}
	}
	if a.frameless() {
		return theme.RenderTitledRule(title, a.width)
	}
	return theme.RenderBorderTitleTrail(title, a.frameTrail(title), a.width)
}

// frameTrail asks the active view for its border trail, within the budget the
// theme leaves after title. It returns "" when there is no room, the view has
// no trail, or the trail is wider than its budget.
func (a *App) frameTrail(title string) string {
	view, ok := a.views[a.currentView]
	if !ok {
		return ""
	}
	tv, ok := view.(FrameTrailView)
	if !ok {
		return ""
	}
	budget := theme.BorderTrailBudget(title, a.width)
	if budget <= 0 {
		return ""
	}
	trail := tv.FrameTrail(budget)
	if lipgloss.Width(trail) > budget {
		return ""
	}
	return trail
}

// frameless reports whether the active view draws its own frames (see
// FramelessView). The default is framed.
func (a *App) frameless() bool {
	view, ok := a.views[a.currentView]
	if !ok {
		return false
	}
	fv, implements := view.(FramelessView)
	return implements && fv.Frameless()
}

// renderViewFooter returns the active view's footer, or "" when it has none.
func (a *App) renderViewFooter() string {
	if view, ok := a.views[a.currentView]; ok {
		if fv, ok := view.(FooterView); ok {
			return fv.RenderFooter(a.width)
		}
	}
	return ""
}

// replaceViewportBottomCorners turns the viewport's bottom └ and ┘ into the
// T-junctions ├ and ┤, so the filter bar rendered below it in the footer joins
// the border into one closed rectangle instead of two stacked boxes.
func replaceViewportBottomCorners(body string) string {
	lastNewline := strings.LastIndex(body, "\n")
	if lastNewline == -1 {
		return body
	}
	lastLine := body[lastNewline+1:]
	lastLine = strings.Replace(lastLine, "└", "├", 1)
	lastLine = strings.Replace(lastLine, "┘", "┤", 1)
	return body[:lastNewline+1] + lastLine
}
package app

import (
	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/jobs"
)

// terminalProgress maps the jobs summary to the terminal tab's progress bar
// (DEVDESK-211). It is pure and returns a fresh pointer on every call: the
// renderer compares through the pointer it kept, so an in-place mutation would
// never be redrawn. nil when idle, which clears the bar.
//
// Error and an unmeasured Warning are drawn full (100): the state is the
// message there, and a full bar stays visible on terminals that hide a 0 value.
func terminalProgress(p jobs.Progress) *tea.ProgressBar {
	switch p.State {
	case jobs.ProgressIndeterminate:
		return tea.NewProgressBar(tea.ProgressBarIndeterminate, 0)
	case jobs.ProgressPercent:
		return tea.NewProgressBar(tea.ProgressBarDefault, p.Percent)
	case jobs.ProgressWarning:
		return tea.NewProgressBar(tea.ProgressBarWarning, p.Percent)
	case jobs.ProgressError:
		return tea.NewProgressBar(tea.ProgressBarError, 100)
	default:
		return nil
	}
}

// summarizeJobs scopes the snapshot to the current context (D8), acknowledges
// the failures when :jobs is on screen and the terminal has the focus (showing
// them is reading them, and a blurred terminal shows nothing to anyone), and
// stores the summary View() reads. Called from Update only (Rule 110).
func (a *App) summarizeJobs(msg jobs.ChangedMsg) {
	runs := jobs.Unfinished(jobs.FilterContext(msg.Runs, msg.Context))
	failures := jobs.FailuresIn(msg.Failures, msg.Context)
	if a.currentView == command.ViewJobs && !a.terminalBlurred {
		if a.failuresReadThrough == nil {
			a.failuresReadThrough = map[string]uint64{}
		}
		a.failuresReadThrough[msg.Context] = max(a.failuresReadThrough[msg.Context], jobs.LatestFailureSeq(failures))
	}
	a.progress = jobs.Summarize(runs, failures, a.failuresReadThrough[msg.Context])
	a.progressContext = msg.Context
}

// syncTerminalProgress is the level check run after every Update: it
// re-summarizes when the context changed since the last summary, or when :jobs
// is on screen, focused, with an unread failure (whatever path brought the view in).
// Otherwise it does nothing, so a tick copies no snapshot.
func (a *App) syncTerminalProgress() {
	if a.currentContext != a.progressContext ||
		(a.currentView == command.ViewJobs && !a.terminalBlurred && a.progress.Unread > 0) {
		a.summarizeJobs(a.changedMsg())
	}
}
package app

import (
	"image/color"

	"charm.land/lipgloss/v2"
	"github.com/charmbracelet/colorprofile"
)

// terminalBackground returns the colour to set as the terminal's own
// background (tea.View.BackgroundColor), or nil when it should be left alone.
//
// It must match what painted cells get on the same profile, otherwise a seam
// shows between them and the terminal background:
//   - TrueColor: the exact colour.
//   - ANSI256: the colour converted to the palette, as the renderer does for cells.
//   - anything else (16 colours, NO_COLOR, not a TTY, unknown): nil, because the
//     approximation would not match the cells.
//
// The renderer compares the result with !=, so it must be a comparable dynamic
// type; both branches return a plain colour value.
func terminalBackground(profile colorprofile.Profile, c color.Color) color.Color {
	if c == nil {
		return nil
	}
	if _, none := c.(lipgloss.NoColor); none {
		return nil
	}
	switch profile {
	case colorprofile.TrueColor:
		return c
	case colorprofile.ANSI256:
		return colorprofile.ANSI256.Convert(c)
	}
	return nil
}
package app

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"image/color"
	"io/fs"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"

	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"
	"github.com/charmbracelet/colorprofile"
	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/ui/configuration"
	"github.com/anthnel/devdesk/internal/ui/testutil"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

func TestTerminalBackgroundByProfile(t *testing.T) {
	bg := lipgloss.Color("#1e1e2e")

	t.Run("TrueColor keeps the exact colour", func(t *testing.T) {
		got := terminalBackground(colorprofile.TrueColor, bg)
		if got == nil || theme.Hex(got) != "#1e1e2e" {
			t.Fatalf("got %v, want #1e1e2e", got)
		}
	})

	t.Run("ANSI256 converts to the colour the painted cells get", func(t *testing.T) {
		got := terminalBackground(colorprofile.ANSI256, bg)
		want := colorprofile.ANSI256.Convert(bg)
		if got != want {
			t.Fatalf("got %#v, want %#v", got, want)
		}
		if _, ok := got.(ansi.IndexedColor); !ok {
			t.Fatalf("got %T, want ansi.IndexedColor", got)
		}
		if got == color.Color(bg) {
			t.Fatal("ANSI256 result equals the exact colour: a seam would show against painted cells")
		}
	})

	for _, tc := range []struct {
		name    string
		profile colorprofile.Profile
		bg      color.Color
	}{
		{"ANSI (16 colours)", colorprofile.ANSI, bg},
		{"ASCII (NO_COLOR)", colorprofile.ASCII, bg},
		{"NoTTY", colorprofile.NoTTY, bg},
		{"Unknown (zero value)", colorprofile.Unknown, bg},
		{"nil colour", colorprofile.TrueColor, nil},
		{"NoColor", colorprofile.TrueColor, lipgloss.NoColor{}},
		{"nil colour, ANSI256", colorprofile.ANSI256, nil},
	} {
		t.Run("nil for "+tc.name, func(t *testing.T) {
			if got := terminalBackground(tc.profile, tc.bg); got != nil {
				t.Fatalf("got %#v, want nil", got)
			}
		})
	}
}

// TestTerminalBackgroundIsComparableOnEveryShippedTheme: the renderer compares
// View.BackgroundColor with !=, so a non-comparable dynamic type would panic.
func TestTerminalBackgroundIsComparableOnEveryShippedTheme(t *testing.T) {
	files, err := filepath.Glob("../../themes/*.json")
	if err != nil {
		t.Fatal(err)
	}
	if len(files) == 0 {
		t.Fatal("no theme found under themes/*.json")
	}
	themes := map[string]*theme.Theme{"default": theme.DefaultTheme()}
	for _, f := range files {
		data, err := os.ReadFile(f)
		if err != nil {
			t.Fatal(err)
		}
		var th theme.Theme
		if err := json.Unmarshal(data, &th); err != nil {
			t.Fatalf("%s: %v", f, err)
		}
		themes[strings.TrimSuffix(filepath.Base(f), ".json")] = &th
	}
	if want := len(files) + 1; len(themes) != want {
		t.Fatalf("got %d themes, want %d (default + %d files)", len(themes), want, len(files))
	}
	t.Cleanup(func() { theme.ApplyTheme(theme.DefaultTheme()) })

	for name, th := range themes {
		for _, p := range []colorprofile.Profile{colorprofile.TrueColor, colorprofile.ANSI256} {
			t.Run(name+"/"+p.String(), func(t *testing.T) {
				theme.ApplyTheme(theme.DefaultTheme())
				theme.ApplyTheme(th)
				got := terminalBackground(p, theme.ColorBackground)
				if got == nil {
					t.Fatal("got nil, want a colour")
				}
				if !reflect.TypeOf(got).Comparable() {
					t.Fatalf("%T is not comparable", got)
				}
				_ = got == terminalBackground(p, theme.ColorBackground) // would panic if not comparable
			})
		}
	}
}

// bgOf returns the terminal background the router asks for, as a hex string or
// "<nil>" when it leaves the terminal alone.
func bgOf(a *App) string {
	c := a.View().BackgroundColor
	if c == nil {
		return "<nil>"
	}
	return fmt.Sprintf("%#v", c)
}

func sendProfile(t *testing.T, a *App, p colorprofile.Profile) {
	t.Helper()
	a.Update(tea.ColorProfileMsg{Profile: p})
}

func TestRouterSetsTheTerminalBackgroundFromTheProfile(t *testing.T) {
	theme.ApplyTheme(theme.DefaultTheme())
	t.Cleanup(func() { theme.ApplyTheme(theme.DefaultTheme()) })

	wantTrue := fmt.Sprintf("%#v", theme.ColorBackground)
	wantIdx := fmt.Sprintf("%#v", colorprofile.ANSI256.Convert(theme.ColorBackground))

	cases := []struct {
		name    string
		profile colorprofile.Profile
		want    string
	}{
		{"TrueColor", colorprofile.TrueColor, wantTrue},
		{"ANSI256", colorprofile.ANSI256, wantIdx},
		{"ANSI", colorprofile.ANSI, "<nil>"},
		{"ASCII", colorprofile.ASCII, "<nil>"},
		{"NoTTY", colorprofile.NoTTY, "<nil>"},
	}

	for _, withOverlay := range []bool{false, true} {
		for _, tc := range cases {
			name := tc.name
			if withOverlay {
				name += "/palette open"
			}
			t.Run(name, func(t *testing.T) {
				a := routerAt(t, &fakeView{body: "hello"}, 80, 24)
				if withOverlay {
					press(t, a, "ctrl+p")
				}
				if got := bgOf(a); got != "<nil>" {
					t.Fatalf("before any ColorProfileMsg: got %s, want nil", got)
				}
				before := a.View().Content

				sendProfile(t, a, tc.profile)

				v := a.View()
				if got := bgOf(a); got != tc.want {
					t.Errorf("got %s, want %s", got, tc.want)
				}
				if v.Content != a.Render() {
					t.Error("View().Content differs from Render()")
				}
				if v.Content != before {
					t.Error("a ColorProfileMsg changed the rendered content")
				}
				if !v.AltScreen {
					t.Error("AltScreen lost")
				}
			})
		}
	}
}

func TestRouterSetsTheTerminalBackgroundWithAnOverlayOpen(t *testing.T) {
	theme.ApplyTheme(theme.DefaultTheme())
	a := routerAt(t, &fakeView{}, 80, 24)
	sendProfile(t, a, colorprofile.TrueColor)
	a.handleKeyMsg(testutil.Key("?"))
	if !a.showHelp {
		t.Fatal("help did not open")
	}
	if got, want := bgOf(a), fmt.Sprintf("%#v", theme.ColorBackground); got != want {
		t.Errorf("help overlay open: got %s, want %s", got, want)
	}
	if v := a.View(); v.Content != a.Render() {
		t.Error("View().Content differs from Render() with the overlay open")
	}
}

func TestRouterFollowsTheLatestProfile(t *testing.T) {
	theme.ApplyTheme(theme.DefaultTheme())
	a := routerAt(t, &fakeView{body: "hello"}, 80, 24)
	sendProfile(t, a, colorprofile.TrueColor)
	if bgOf(a) == "<nil>" {
		t.Fatal("TrueColor: want a colour")
	}
	sendProfile(t, a, colorprofile.ASCII)
	if got := bgOf(a); got != "<nil>" {
		t.Errorf("TrueColor then ASCII: got %s, want nil", got)
	}
	sendProfile(t, a, colorprofile.TrueColor)
	if bgOf(a) == "<nil>" {
		t.Error("ASCII then TrueColor: want a colour again")
	}
}

func TestColorProfileMsgDoesNotReachTheActiveView(t *testing.T) {
	fv := &fakeView{body: "hello"}
	a := routerAt(t, fv, 80, 24)
	sendProfile(t, a, colorprofile.TrueColor)
	for _, m := range fv.received {
		if _, ok := m.(tea.ColorProfileMsg); ok {
			t.Error("the router forwarded a ColorProfileMsg to the active view")
		}
	}
}

// TestOnlyTheRouterSetsTheTerminalBackground: the terminal's background is
// terminal state, so like AltScreen only the router (internal/app/view.go)
// sets it. Any other assignment or composite-literal field named
// BackgroundColor in non-test code is reported with file:line.
func TestOnlyTheRouterSetsTheTerminalBackground(t *testing.T) {
	assertOnlyOwnerSets(t, "internal/app/view.go", "BackgroundColor")
}

// assertOnlyOwnerSets walks the non-test sources and fails on any assignment or
// composite-literal key named field outside owner (file:line), and when owner
// itself never sets it (the guard would pass vacuously).
func assertOnlyOwnerSets(t *testing.T, owner, field string) {
	t.Helper()
	root := filepath.Join("..", "..")
	fset := token.NewFileSet()
	var offences []string
	ownerSets := false

	err := walkProductionGo(root, func(rel, path string) error {
		f, err := parser.ParseFile(fset, path, nil, 0)
		if err != nil {
			return err
		}
		report := func(pos token.Pos) {
			if rel == owner {
				ownerSets = true
				return
			}
			offences = append(offences, fset.Position(pos).String())
		}
		ast.Inspect(f, func(n ast.Node) bool {
			switch x := n.(type) {
			case *ast.AssignStmt:
				for _, lhs := range x.Lhs {
					if sel, ok := lhs.(*ast.SelectorExpr); ok && sel.Sel.Name == field {
						report(sel.Pos())
					}
				}
			case *ast.KeyValueExpr:
				if id, ok := x.Key.(*ast.Ident); ok && id.Name == field {
					report(id.Pos())
				}
			}
			return true
		})
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	for _, o := range offences {
		t.Errorf("%s sets %s; only %s may (the router owns terminal state)", o, field, owner)
	}
	if !ownerSets {
		t.Errorf("%s never assigns %s: the guard would pass vacuously", owner, field)
	}
}

// walkProductionGo calls visit for every non-test .go file under root, with its
// slash path relative to root.
func walkProductionGo(root string, visit func(rel, path string) error) error {
	return filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(root, path)
		rel = filepath.ToSlash(rel)
		if d.IsDir() {
			switch d.Name() {
			case ".git", ".worktrees", "vendor", "node_modules":
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(rel, ".go") || strings.HasSuffix(rel, "_test.go") {
			return nil
		}
		return visit(rel, path)
	})
}

// writeTheme writes a valid theme named name under the isolated HOME's theme
// directory, with the given background.
func writeTheme(t *testing.T, name, background string) {
	t.Helper()
	dir, err := theme.ThemeDir()
	if err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	th := theme.DefaultTheme()
	th.Name = name
	th.ColorBackground = background
	data, err := json.Marshal(th)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, name+".json"), data, 0o644); err != nil {
		t.Fatal(err)
	}
}

func bgHex(a *App) string {
	c := a.View().BackgroundColor
	if c == nil {
		return "<nil>"
	}
	return theme.Hex(c)
}

func saveTheme(a *App, name string) {
	cfg := testConfig()
	cfg.App.Theme = name
	a.Update(configuration.ConfigSavedMsg{Config: cfg, ThemeChanged: true})
}

func resetThemeAfter(t *testing.T) {
	t.Helper()
	t.Cleanup(func() {
		theme.ApplyTheme(theme.DefaultTheme())
		theme.CurrentThemeName = "default"
	})
	theme.ApplyTheme(theme.DefaultTheme())
	theme.CurrentThemeName = "default"
}

// DEVDESK-209 step 3: the terminal background follows the theme.
func TestTheTerminalBackgroundFollowsTheTheme(t *testing.T) {
	a := router(t, &fakeView{body: "hello"}) // isolates HOME
	resetThemeAfter(t)
	writeTheme(t, "light", "#ffffff")
	sendProfile(t, a, colorprofile.TrueColor)
	if got := bgHex(a); got != "#1e1e2e" {
		t.Fatalf("default theme: got %s, want #1e1e2e", got)
	}

	saveTheme(a, "light")
	if got := bgHex(a); got != "#ffffff" {
		t.Errorf("after switching to the light theme: got %s, want #ffffff", got)
	}

	saveTheme(a, "default")
	if got := bgHex(a); got != "#1e1e2e" {
		t.Errorf("after switching back to the default theme: got %s, want #1e1e2e", got)
	}
}

func TestARefusedThemeKeepsThePreviousTerminalBackground(t *testing.T) {
	a := router(t, &fakeView{body: "hello"})
	resetThemeAfter(t)
	writeTheme(t, "light", "#ffffff")
	writeTheme(t, "broken", "#ggg")
	sendProfile(t, a, colorprofile.TrueColor)

	saveTheme(a, "broken")
	if got := bgHex(a); got != "#1e1e2e" {
		t.Errorf("refused theme from default: got %s, want #1e1e2e kept", got)
	}

	saveTheme(a, "light")
	saveTheme(a, "broken")
	if got := bgHex(a); got != "#ffffff" {
